function ContradictionCreatePanel({ say }: { say: (message: string) => void }) { const [subject, setSubject] = useState(""); const [description, setDescription] = useState(""); const [leftId, setLeftId] = useState(""); const [rightId, setRightId] = useState(""); const [busy, setBusy] = useState(false); const submit = async () => { if (!subject.trim() || !description.trim() || !leftId.trim() || !rightId.trim()) return say("Subject, documented difference, and two source IDs are required."); if (!window.confirm("Create this contradiction record? This writes case data and an audit event.")) return; setBusy(true); try { await createContradiction(currentCaseId, { subject, description, sources: [{ source_type: "evidence", source_id: leftId, relationship: "challenges" }, { source_type: "evidence", source_id: rightId, relationship: "challenges" }] }); await refreshCurrentAnalysis(); say("Contradiction record created with source links and audit record."); setSubject(""); setDescription(""); setLeftId(""); setRightId(""); } catch (error) { say(getApiErrorMessage(error, "Contradiction could not be created.")); } finally { setBusy(false); } }; return <Panel className="mb-5 p-4"><Eyebrow>Structured contradiction / confirmation required</Eyebrow><p className="mt-1 text-[9px] leading-4 text-[#aaa49a]">Record only an exact documented difference with two existing case evidence IDs. The action remains subject to a browser confirmation.</p><div className="mt-3 grid gap-2 sm:grid-cols-2"><input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="Subject" className={gateInput}/><input value={leftId} onChange={(event) => setLeftId(event.target.value)} placeholder="First evidence ID" className={gateInput}/><input value={rightId} onChange={(event) => setRightId(event.target.value)} placeholder="Second evidence ID" className={gateInput}/><button disabled={busy} onClick={submit} className="rounded bg-[#873e38] px-3 py-2 text-[9px] font-bold disabled:opacity-60">{busy ? "Saving…" : "Create contradiction"}</button></div><textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Exact documented difference" className={`${gateInput} mt-2 min-h-20`}/></Panel>; }
