function PreferenceUpdatePanel({ say }: { say: (message: string) => void }) { const [category, setCategory] = useState("processing"); const [enabled, setEnabled] = useState(true); const [busy, setBusy] = useState(false); const submit = async () => { if (!category.trim()) return say("Enter a preference category."); if (!window.confirm(`Update in-app preference ${category} to ${enabled ? "enabled" : "disabled"}? This writes a preference and audit event but sends no external message.`)) return; setBusy(true); try { await updateNotificationPreference(category, enabled); await refreshCurrentNotifications(); say("In-app preference saved with its audit record; no external message was sent."); } catch (error) { say(getApiErrorMessage(error, "Preference could not be updated.")); } finally { setBusy(false); } }; return <Panel className="mb-5 p-4"><Eyebrow>In-app preference / confirmation required</Eyebrow><p className="mt-1 text-[9px] leading-4 text-[#aaa49a]">Only a named in-app preference is updated. No email, WhatsApp, push, or outbound delivery is configured.</p><div className="mt-3 flex flex-wrap gap-2"><input value={category} onChange={(event) => setCategory(event.target.value)} placeholder="Category" className={gateInput}/><select value={enabled ? "enabled" : "disabled"} onChange={(event) => setEnabled(event.target.value === "enabled")} className={gateInput}><option value="enabled">Enabled</option><option value="disabled">Disabled</option></select><button disabled={busy} onClick={submit} className="rounded bg-[#873e38] px-3 py-2 text-[9px] font-bold disabled:opacity-60">{busy ? "Saving…" : "Save preference"}</button></div></Panel>; }
