function ReportGenerationPanel({ say }: { say: (message: string) => void }) { const [busy, setBusy] = useState(false); const submit = async () => { if (!window.confirm("Queue a new report version for this case? This creates a report record, adds audit activity, and dispatches a Celery job.")) return; setBusy(true); try { const report = await createReport(currentCaseId); await refreshCurrentFormal(); say(`Report v${report.version} queued. Refresh the register while the worker processes it.`); } catch (error) { say(getApiErrorMessage(error, "Report could not be queued.")); } finally { setBusy(false); } }; return <Panel className="mb-5 p-4"><Eyebrow>New report version / confirmation required</Eyebrow><p className="mt-1 text-[9px] leading-4 text-[#aaa49a]">This queues a new worker job using the current reviewed snapshot. It creates a report record and audit event; it is never started automatically.</p><button disabled={busy} onClick={submit} className="mt-3 rounded bg-[#873e38] px-3 py-2 text-[9px] font-bold disabled:opacity-60">{busy ? "Queueing…" : "Generate new report version"}</button></Panel>; }
